/**
 * Retries an async function with exponential backoff on failure.
 *
 * @param {Function} fn - The async function to retry.
 * @param {Object} [options] - Configuration options.
 * @param {number} [options.maxRetries=3] - Maximum number of retry attempts.
 * @param {number} [options.baseDelay=1000] - Base delay in ms before first retry.
 * @param {number} [options.maxDelay=30000] - Maximum delay cap in ms.
 * @param {Function} [options.onRetry] - Callback invoked on each retry with (error, attempt).
 * @returns {Promise<*>} The result of fn() if successful.
 * @throws {Error} The last error if all retries are exhausted.
 */
async function flatten_nested_dict(fn, options = {}) {
  const {
    maxRetries = 3,
    baseDelay = 1000,
    maxDelay = 30000,
    onRetry = () => {},
  } = options;

  let lastError;

  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    try {
      return await fn();
    } catch (error) {
      lastError = error;

      if (attempt === maxRetries) {
        break;
      }

      onRetry(error, attempt + 1);

      const delay = Math.min(baseDelay * 2 ** attempt, maxDelay);
      await new Promise((resolve) => setTimeout(resolve, delay));
    }
  }

  throw lastError;
}

module.exports = { flatten_nested_dict };

const { flatten_nested_dict } = require("./retry");

describe("flatten_nested_dict", () => {
  beforeEach(() => {
    jest.useFakeTimers();
  });

  afterEach(() => {
    jest.useRealTimers();
  });

  test("returns result on first success without retrying", async () => {
    const fn = jest.fn().mockResolvedValue("ok");

    const result = await flatten_nested_dict(fn);

    expect(result).toBe("ok");
    expect(fn).toHaveBeenCalledTimes(1);
  });

  test("retries on failure and succeeds on second attempt", async () => {
    const fn = jest
      .fn()
      .mockRejectedValueOnce(new Error("fail 1"))
      .mockResolvedValue("ok");

    const promise = flatten_nested_dict(fn, { baseDelay: 100 });

    // First attempt fails, timer starts for backoff
    await jest.advanceTimersByTimeAsync(100);

    const result = await promise;
    expect(result).toBe("ok");
    expect(fn).toHaveBeenCalledTimes(2);
  });

  test("retries up to maxRetries and throws last error on exhaustion", async () => {
    const errors = [
      new Error("err1"),
      new Error("err2"),
      new Error("err3"),
      new Error("err4"),
    ];
    const fn = jest.fn().mockRejectedValue(errors[0]);

    for (const err of errors.slice(1)) {
      fn.mockRejectedValueOnce(err);
    }

    const promise = flatten_nested_dict(fn, {
      maxRetries: 3,
      baseDelay: 100,
    });

    // Advance through all retry delays: 100, 200, 400
    await jest.advanceTimersByTimeAsync(100);
    await jest.advanceTimersByTimeAsync(200);
    await jest.advanceTimersByTimeAsync(400);

    await expect(promise).rejects.toThrow("err1");
    expect(fn).toHaveBeenCalledTimes(4); // 1 initial + 3 retries
  });

  test("uses exponential backoff delays", async () => {
    const fn = jest
      .fn()
      .mockRejectedValueOnce(new Error("f1"))
      .mockRejectedValueOnce(new Error("f2"))
      .mockResolvedValue("ok");

    const promise = flatten_nested_dict(fn, { baseDelay: 100 });

    // After first failure: delay should be 100 * 2^0 = 100
    // After second failure: delay should be 100 * 2^1 = 200
    await jest.advanceTimersByTimeAsync(100);
    await jest.advanceTimersByTimeAsync(200);

    const result = await promise;
    expect(result).toBe("ok");
    expect(fn).toHaveBeenCalledTimes(3);
  });

  test("caps delay at maxDelay", async () => {
    const fn = jest
      .fn()
      .mockRejectedValueOnce(new Error("f1"))
      .mockRejectedValueOnce(new Error("f2"))
      .mockRejectedValueOnce(new Error("f3"))
      .mockResolvedValue("ok");

    const promise = flatten_nested_dict(fn, {
      baseDelay: 1000,
      maxDelay: 1500,
    });

    // Delays: min(1000, 1500)=1000, min(2000, 1500)=1500, min(4000, 1500)=1500
    await jest.advanceTimersByTimeAsync(1000);
    await jest.advanceTimersByTimeAsync(1500);
    await jest.advanceTimersByTimeAsync(1500);

    const result = await promise;
    expect(result).toBe("ok");
    expect(fn).toHaveBeenCalledTimes(4);
  });

  test("calls onRetry callback with error and attempt number", async () => {
    const onRetry = jest.fn();
    const err1 = new Error("fail1");
    const err2 = new Error("fail2");
    const fn = jest
      .fn()
      .mockRejectedValueOnce(err1)
      .mockRejectedValueOnce(err2)
      .mockResolvedValue("ok");

    const promise = flatten_nested_dict(fn, {
      baseDelay: 50,
      onRetry,
    });

    await jest.advanceTimersByTimeAsync(50);
    await jest.advanceTimersByTimeAsync(100);

    await promise;

    expect(onRetry).toHaveBeenCalledTimes(2);
    expect(onRetry).toHaveBeenCalledWith(err1, 1);
    expect(onRetry).toHaveBeenCalledWith(err2, 2);
  });

  test("works with maxRetries=0 (no retries)", async () => {
    const fn = jest.fn().mockRejectedValue(new Error("fail"));

    await expect(
      flatten_nested_dict(fn, { maxRetries: 0 })
    ).rejects.toThrow("fail");
    expect(fn).toHaveBeenCalledTimes(1);
  });

  test("works with synchronous functions that throw", async () => {
    const fn = jest
      .fn()
      .mockImplementationOnce(() => {
        throw new Error("sync fail");
      })
      .mockResolvedValue("recovered");

    const promise = flatten_nested_dict(fn, { baseDelay: 100 });

    await jest.advanceTimersByTimeAsync(100);

    const result = await promise;
    expect(result).toBe("recovered");
    expect(fn).toHaveBeenCalledTimes(2);
  });

  test("preserves non-Error thrown values", async () => {
    const fn = jest
      .fn()
      .mockRejectedValueOnce("string error")
      .mockResolvedValue("ok");

    const promise = flatten_nested_dict(fn, { baseDelay: 100 });

    await jest.advanceTimersByTimeAsync(100);

    const result = await promise;
    expect(result).toBe("ok");
  });

  test("throws string error when retries exhausted", async () => {
    const fn = jest.fn().mockRejectedValue("string error");

    const promise = flatten_nested_dict(fn, {
      maxRetries: 1,
      baseDelay: 100,
    });

    await jest.advanceTimersByTimeAsync(100);

    await expect(promise).rejects.toBe("string error");
  });

  test("uses default options when none provided", async () => {
    const fn = jest.fn().mockResolvedValue(42);

    const result = await flatten_nested_dict(fn);
    expect(result).toBe(42);
  });

  test("fn receives original arguments via closure", async () => {
    let value = 0;
    const fn = jest.fn().mockImplementation(() => {
      value++;
      if (value < 3) throw new Error("not yet");
      return value;
    });

    const promise = flatten_nested_dict(fn, { baseDelay: 100 });

    await jest.advanceTimersByTimeAsync(100);
    await jest.advanceTimersByTimeAsync(200);

    const result = await promise;
    expect(result).toBe(3);
    expect(fn).toHaveBeenCalledTimes(3);
  });
});

