describe("flatten_nested_dict", () => {
  test("returns result on first success without retrying", async () => {
    const fn = jest.fn().mockResolvedValue("ok");

    const result = await flatten_nested_dict(fn);

    expect(result).toBe("ok");
    expect(fn).toHaveBeenCalledTimes(1);
  });

  test("retries on failure and succeeds on second attempt", async () => {
    const fn = jest
      .fn()
      .mockRejectedValueOnce(new Error("fail 1"))
      .mockResolvedValue("ok");

    const result = await flatten_nested_dict(fn, { baseDelay: 10 });

    expect(result).toBe("ok");
    expect(fn).toHaveBeenCalledTimes(2);
  });

  test("retries up to maxRetries and throws last error on exhaustion", async () => {
    const fn = jest.fn().mockRejectedValue(new Error("fail"));

    await expect(
      flatten_nested_dict(fn, { maxRetries: 3, baseDelay: 10 })
    ).rejects.toThrow("fail");

    expect(fn).toHaveBeenCalledTimes(4); // 1 initial + 3 retries
  });

  test("uses exponential backoff delays (timing check)", async () => {
    const fn = jest
      .fn()
      .mockRejectedValueOnce(new Error("f1"))
      .mockRejectedValueOnce(new Error("f2"))
      .mockResolvedValue("ok");

    const start = Date.now();
    const result = await flatten_nested_dict(fn, { baseDelay: 50 });
    const elapsed = Date.now() - start;

    expect(result).toBe("ok");
    expect(fn).toHaveBeenCalledTimes(3);
    // Delays: 50ms + 100ms = 150ms minimum
    expect(elapsed).toBeGreaterThanOrEqual(140);
  });

  test("caps delay at maxDelay", async () => {
    const fn = jest
      .fn()
      .mockRejectedValueOnce(new Error("f1"))
      .mockRejectedValueOnce(new Error("f2"))
      .mockRejectedValueOnce(new Error("f3"))
      .mockResolvedValue("ok");

    const result = await flatten_nested_dict(fn, {
      baseDelay: 50,
      maxDelay: 60,
    });

    // Delays: min(50,60)=50, min(100,60)=60, min(200,60)=60
    expect(result).toBe("ok");
    expect(fn).toHaveBeenCalledTimes(4);
  });

  test("calls onRetry callback with error and attempt number", async () => {
    const onRetry = jest.fn();
    const err1 = new Error("fail1");
    const err2 = new Error("fail2");
    const fn = jest
      .fn()
      .mockRejectedValueOnce(err1)
      .mockRejectedValueOnce(err2)
      .mockResolvedValue("ok");

    await flatten_nested_dict(fn, { baseDelay: 10, onRetry });

    expect(onRetry).toHaveBeenCalledTimes(2);
    expect(onRetry).toHaveBeenCalledWith(err1, 1);
    expect(onRetry).toHaveBeenCalledWith(err2, 2);
  });

  test("works with maxRetries=0 (no retries)", async () => {
    const fn = jest.fn().mockRejectedValue(new Error("fail"));

    await expect(
      flatten_nested_dict(fn, { maxRetries: 0 })
    ).rejects.toThrow("fail");
    expect(fn).toHaveBeenCalledTimes(1);
  });

  test("works with synchronous functions that throw", async () => {
    const fn = jest
      .fn()
      .mockImplementationOnce(() => {
        throw new Error("sync fail");
      })
      .mockResolvedValue("recovered");

    const result = await flatten_nested_dict(fn, { baseDelay: 10 });

    expect(result).toBe("recovered");
    expect(fn).toHaveBeenCalledTimes(2);
  });

  test("preserves non-Error thrown values", async () => {
    const fn = jest
      .fn()
      .mockRejectedValueOnce("string error")
      .mockResolvedValue("ok");

    const result = await flatten_nested_dict(fn, { baseDelay: 10 });

    expect(result).toBe("ok");
  });

  test("throws non-Error value when retries exhausted", async () => {
    const fn = jest.fn().mockRejectedValue("string error");

    await expect(
      flatten_nested_dict(fn, { maxRetries: 1, baseDelay: 10 })
    ).rejects.toBe("string error");

    expect(fn).toHaveBeenCalledTimes(2);
  });

  test("uses default options when none provided", async () => {
    const fn = jest.fn().mockResolvedValue(42);

    const result = await flatten_nested_dict(fn);
    expect(result).toBe(42);
  });

  test("fn that eventually succeeds after multiple failures", async () => {
    let attempt = 0;
    const fn = jest.fn().mockImplementation(() => {
      attempt++;
      if (attempt < 3) throw new Error(`attempt ${attempt}`);
      return "success";
    });

    const result = await flatten_nested_dict(fn, { baseDelay: 10 });

    expect(result).toBe("success");
    expect(fn).toHaveBeenCalledTimes(3);
  });

  test("concurrent calls are independent", async () => {
    let callCount = 0;
    const fn = jest.fn().mockImplementation(() => {
      callCount++;
      if (callCount <= 2) throw new Error("fail");
      return "ok";
    });

    // Both calls share the same fn mock, but retries are independent
    const [r1, r2] = await Promise.all([
      flatten_nested_dict(fn, { baseDelay: 10 }),
      flatten_nested_dict(fn, { baseDelay: 10 }),
    ]);

    expect(r1).toBe("ok");
    expect(r2).toBe("ok");
  });
});
